messages.content:
Components MUST be attached to Nodes. Never 'new Component(context)' alone.

Pattern:
```cpp
// 1. Create a Node
Node* myNode = scene_->CreateChild("MyObject");

// 2. Attach components TO that node
auto* model = myNode->CreateComponent<StaticModel>();
auto* body = myNode->CreateComponent<RigidBody>();
auto* shape = myNode->CreateComponent<CollisionShape>();
auto* light = myNode->CreateComponent<Light>();
auto* camera = myNode->CreateComponent<Camera>();
auto* sound = myNode->CreateComponent<SoundSource3D>();
```

WRONG:
```cpp
Light* light = new Light(context);  // WRONG - component without node
scene->AddChild(light);              // WRONG - can't add component as child
```

Nodes hold position. Components define behavior. A Node without components is just a transform. A component without a node cannot exist.

```cpp
scene_ = new Scene(context_);
scene_->CreateComponent<Octree>();

Node* lightNode = scene_->CreateChild("DirectionalLight");
lightNode->SetDirection(Vector3(0.6f, -1.0f, 0.8f));
auto* light = lightNode->CreateComponent<Light>();
light->SetLightType(LIGHT_DIRECTIONAL);
light->SetCastShadows(true);
```

Octree is a component on the Scene node — CreateComponent, not SetOctreeEnabled.
Light is a component on a child node — CreateComponent, not new Light.

```cpp
Node* cameraNode = scene_->CreateChild("Camera");
cameraNode->SetPosition(Vector3(0.0f, 5.0f, -10.0f));
auto* camera = cameraNode->CreateComponent<Camera>();
camera->SetFarClip(300.0f);

auto* renderer = GetSubsystem<Renderer>();
SharedPtr<Viewport> viewport(new Viewport(context_, scene_, camera));
renderer->SetViewport(0, viewport);
```

Camera is a Component — attach to a Node with CreateComponent.
Viewport is NOT a component — create with new and set on Renderer.

```cpp
auto* cache = GetSubsystem<ResourceCache>();

Node* mushroomNode = scene_->CreateChild("Mushroom");
mushroomNode->SetPosition(Vector3(0.0f, 0.0f, 3.0f));
mushroomNode->SetScale(2.0f);

auto* model = mushroomNode->CreateComponent<StaticModel>();
model->SetModel(cache->GetResource<Model>("Models/Mushroom.mdl"));
model->SetMaterial(cache->GetResource<Material>("Materials/Mushroom.xml"));
model->SetCastShadows(true);
```

Model is a Resource — loaded with GetResource<Model>.
StaticModel is a Component — created with CreateComponent<StaticModel>.
Material is a Resource — loaded with GetResource<Material>.
Never GetResource<StaticModel> — StaticModel is not a resource.

```cpp
void MyApp::Start()
{
    Sample::Start();

    auto* cache = GetSubsystem<ResourceCache>();

    // Create scene
    scene_ = new Scene(context_);
    scene_->CreateComponent<Octree>();

    // Directional light
    Node* lightNode = scene_->CreateChild("Light");
    lightNode->SetDirection(Vector3(0.6f, -1.0f, 0.8f));
    auto* light = lightNode->CreateComponent<Light>();
    light->SetLightType(LIGHT_DIRECTIONAL);

    // Camera
    Node* cameraNode = scene_->CreateChild("Camera");
    cameraNode->SetPosition(Vector3(0.0f, 5.0f, -10.0f));
    cameraNode->LookAt(Vector3::ZERO);
    auto* camera = cameraNode->CreateComponent<Camera>();

    // Object
    Node* boxNode = scene_->CreateChild("Box");
    auto* model = boxNode->CreateComponent<StaticModel>();
    model->SetModel(cache->GetResource<Model>("Models/Box.mdl"));
    model->SetMaterial(cache->GetResource<Material>("Materials/Stone.xml"));

    // Viewport
    auto* renderer = GetSubsystem<Renderer>();
    SharedPtr<Viewport> viewport(new Viewport(context_, scene_, camera));
    renderer->SetViewport(0, viewport);

    // Events
    SubscribeToEvent(E_UPDATE, URHO3D_HANDLER(MyApp, HandleUpdate));
}
```

This is the standard flow: Scene → Octree → Light → Camera → Objects → Viewport → Events.

Model — a RESOURCE. Mesh data loaded from .mdl files. Load with GetResource<Model>(path).

StaticModel — a COMPONENT. Displays a static (non-animated) Model. Attach to a Node with CreateComponent<StaticModel>().

AnimatedModel — a COMPONENT. Displays a skeletal Model with bone animations. Attach to a Node with CreateComponent<AnimatedModel>().

```cpp
auto* cache = GetSubsystem<ResourceCache>();

// Static object (no animation)
auto* sm = node->CreateComponent<StaticModel>();
sm->SetModel(cache->GetResource<Model>("Models/Box.mdl"));

// Animated character
auto* am = charNode->CreateComponent<AnimatedModel>();
am->SetModel(cache->GetResource<Model>("Models/Animals/Fox.mdl"));
```

You LOAD a Model (resource). You CREATE a StaticModel or AnimatedModel (component). Never load a component through ResourceCache.
